import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.CslsFoWx.js";const s="/VendoraSystem-docs/captures/2026-10-29-etiquettes-android/01-planche-a4-gabarit24-case5.png",i="/VendoraSystem-docs/captures/2026-10-29-etiquettes-android/02-caisse-pain-maison-synchronise-code-interne.png",n="/VendoraSystem-docs/captures/2026-10-29-etiquettes-android/03-scan-douchette-pain-maison-au-panier.png",f=JSON.parse('{"title":"Étiquettes produits — preuve côté caisse Android (2026-10-29)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-10-29-etiquettes-android.md","filePath":"generated/preuves/2026-10-29-etiquettes-android.md","lastUpdated":null}'),d={name:"preuves/2026-10-29-etiquettes-android.md"};function c(l,e,p,u,g,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="etiquettes-produits-—-preuve-cote-caisse-android-2026-10-29" tabindex="-1">Étiquettes produits — preuve côté caisse Android (2026-10-29) <a class="header-anchor" href="#etiquettes-produits-—-preuve-cote-caisse-android-2026-10-29" aria-label="Permalink to &quot;Étiquettes produits — preuve côté caisse Android (2026-10-29)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-10-29-etiquettes-android</code> · 3 image(s) · 0 trace(s)</p><div><p>Spec 11 RG-HW-11 / CA-10, spec 02 RG-CAT-42/45. Côté caisse <strong>rien ne change</strong> : un code EAN-13 interne attribué par le serveur arrive par le pull (<code>ProductUpdated</code>) et se scanne comme n&#39;importe quel code (lookup local <code>byBarcode</code> existant). Ce lot est une <strong>preuve</strong>, sans code de production modifié.</p><p>Environnement : émulateur <code>emulator-5554</code> appairé au serveur local (<code>10.0.2.2:8080</code>), magasin « Épicerie Omar Centre », utilisateur <strong>omar</strong> (PIN), <strong>Session #7</strong> ouverte. Serveur : <code>docker compose up -d</code> + <code>./gradlew :server:bootRun</code> (arrêté à la fin).</p><h2 id="deroule-reel-api-localhost" tabindex="-1">Déroulé réel (API, localhost) <a class="header-anchor" href="#deroule-reel-api-localhost" aria-label="Permalink to &quot;Déroulé réel (API, localhost)&quot;">​</a></h2><ol><li>Login <code>POST /api/v1/auth/login</code> (compte de test des fixtures).</li><li><code>POST /api/v1/catalog/products</code> : <strong>« Pain maison »</strong>, 0,800 TND, TVA 7 %, <strong>sans code-barres</strong> → <code>version 1</code>, <code>barcode: null</code>.</li><li><code>POST /api/v1/catalog/internal-barcodes {productIds:[…]}</code> → <code>[{&quot;barcode&quot;:&quot;2000000000015&quot;}]</code> (préfixe 20 + séquence 1 + clé GS1 5), émission de <code>ProductUpdated</code>.</li><li><code>POST /api/v1/stores/{storeId}/label-sheets {template: 24, startPosition: 5}</code> → PDF A4 rendu (HTTP 200, <code>application/pdf</code>).</li><li>Caisse : le pull (« Synchronisé à 19:35 ») a projeté le produit avec son code.</li><li>Scan douchette simulé (KeyEvents système, comme une douchette HID) : <code>adb shell input text 2000000000015 &amp;&amp; adb shell input keyevent 66</code> → <strong>« Pain maison × 1 — 0,800 TND »</strong> au panier, total 0,800 TND.</li><li>Panier vidé (« Vider le panier »).</li></ol><h2 id="fichiers" tabindex="-1">Fichiers <a class="header-anchor" href="#fichiers" aria-label="Permalink to &quot;Fichiers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fichier</th><th>Contenu</th></tr></thead><tbody><tr><td><code>01-planche-a4-gabarit24-case5.pdf</code></td><td>Planche A4 rendue par le serveur (gabarit 24 = 3 × 8, départ case 5)</td></tr><tr><td><code>01-planche-a4-gabarit24-case5.png</code></td><td>La même page en PNG (<code>qlmanage</code>) : étiquette en <strong>ligne 2, colonne 2</strong> (case 5), nom, prix TTC « 0,800 DT », EAN-13 <code>2000000000015</code></td></tr><tr><td><code>02-caisse-pain-maison-synchronise-code-interne.png</code></td><td>Écran de vente après pull : « Pain maison » avec le code <code>2000000000015</code>, panier vide</td></tr><tr><td><code>03-scan-douchette-pain-maison-au-panier.png</code></td><td>Après la rafale douchette : « Pain maison × 1 », total <strong>0,800 TND</strong></td></tr></tbody></table><h2 id="tests-jvm-androidapp-src-test-register-internalbarcodescantest-kt" tabindex="-1">Tests JVM (<code>androidApp/src/test/.../register/InternalBarcodeScanTest.kt</code>) <a class="header-anchor" href="#tests-jvm-androidapp-src-test-register-internalbarcodescantest-kt" aria-label="Permalink to &quot;Tests JVM (`androidApp/src/test/.../register/InternalBarcodeScanTest.kt`)&quot;">​</a></h2><p>Base SQLDelight in-memory, <strong>la</strong> composition d&#39;applier du pull de l&#39;app (<code>posEventApplier</code>), douchette <code>WedgeKeyRouter</code> (rafale 5 ms + Entrée) → <code>CatalogViewModel.onBarcodeScanned</code> :</p><ul><li><code>ProductUpdated</code> (code <code>Barcodes.internalEan13(&quot;20&quot;, 1)</code>) appliqué → le scan ajoute « Pain maison » au panier (0,800 TND, événement <code>Added</code>) ;</li><li>même produit avant attribution (sans code) → <code>ScanEvent.Unknown</code>, panier intact, code laissé dans la recherche (RG-SALE-03).</li></ul><p><code>./gradlew :androidApp:testDebugUnitTest --rerun-tasks</code> : <strong>101 tests, 0 échec</strong> (99 avant).</p><h2 id="mise-a-jour-du-rendu-relecture" tabindex="-1">Mise à jour du rendu (relecture) <a class="header-anchor" href="#mise-a-jour-du-rendu-relecture" aria-label="Permalink to &quot;Mise à jour du rendu (relecture)&quot;">​</a></h2><p>La planche <code>01-*</code> a été <strong>régénérée</strong> après relecture : la première version faisait passer la garde centrale du code-barres à travers les chiffres et collait le prix aux barres. Le rendu suit désormais la disposition GS1 (1er chiffre dans la marge gauche, 6 chiffres sous chaque moitié, gardes entre les groupes) ; les 10 codes du test CA-10 restent relus par ZXing aux cases 5 à 14.</p></div><h2 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h2><div class="proof-grid"><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-etiquettes-android/01-planche-a4-gabarit24-case5.png" target="_blank"><img src="'+s+'" alt="01-planche-a4-gabarit24-case5.png" loading="lazy"></a><figcaption>01-planche-a4-gabarit24-case5.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-etiquettes-android/02-caisse-pain-maison-synchronise-code-interne.png" target="_blank"><img src="'+i+'" alt="02-caisse-pain-maison-synchronise-code-interne.png" loading="lazy"></a><figcaption>02-caisse-pain-maison-synchronise-code-interne.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-etiquettes-android/03-scan-douchette-pain-maison-au-panier.png" target="_blank"><img src="'+n+'" alt="03-scan-douchette-pain-maison-au-panier.png" loading="lazy"></a><figcaption>03-scan-douchette-pain-maison-au-panier.png</figcaption></figure></div>',5)])])}const v=a(d,[["render",c]]);export{f as __pageData,v as default};
